window.addEventListener('resize',()=>{if(!panel.hidden){size();drawStart()}});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(frame);frame=0;audio?.suspend().catch(()=>{})}else if(!panel.hidden)drawStart()});window.addEventListener('pagehide',()=>{sequence++;clearTimeout(timer);clearTimeout(arrivalTimer);clearInterval(clockTimer);cancelAnimationFrame(frame);audio?.close().catch(()=>{})});
window.GameStartup={replay,ready,timings:{brand:6600,atmosphere:6900,referenceFrames:108}};
